                                    $default_id_cuello = null;

                                    // Establecer valor por defecto si no hay uno ya guardado
                                    if (in_array($fila['id_prenda'], $grupo_1)) {
                                        $default_id_cuello = 3;
                                    } elseif (in_array($fila['id_prenda'], $grupo_2)) {
                                        $default_id_cuello = 2;
                                    } elseif (in_array($fila['id_prenda'], $grupo_3)) {
                                        $default_id_cuello = 5;
